import sqlite3
import pandas as pd
sql_query="""
SELECT "Customer_ID", "Customer_Details"
   FROM "Customers"
   LIMIT 100;
"""
sqlite_path = '/workspace/ashwin/fine-tuning/snow-spider-agent/methods/RL-fine-tuning/data/Spider/spider_data/database/insurance_policies/insurance_policies.sqlite'
max_len = 100
uri = f"file:{sqlite_path}?mode=ro"
conn = sqlite3.connect(uri, uri=True, timeout=60)
cursor = conn.cursor()
cursor.execute("PRAGMA read_uncommitted = true;")
cursor.execute(sql_query)
# Fetch the results
results = cursor.fetchall()
results = results[:max_len] if len(results) > max_len else results
columns = [desc[0] for desc in cursor.description]
df = pd.DataFrame(results, columns=columns)

print(results)